sdk_generation.command:
node --max-old-space-size=512 --input-type=module - <<'NODE'
import * as esbuild from 'esbuild';import fs from 'node:fs';import {resolve} from 'node:path';import {spawnSync} from 'node:child_process';import {createHash} from 'node:crypto';
const version=fs.readFileSync('src/sdk/version.ts','utf8').match(/'([^']+)'/)[1],banner='/* edge-personalization SDK v'+version+' — one package: core (identity, transport), emit (four capture paths), listen (decisions). */';
const outputs=[];
for(const [entry,out,format] of [['src/sdk/index.ts','public/sdk/edge-personalization.esm.js','esm'],['src/sdk/browser.ts','public/sdk/edge-personalization.js','iife']]){
const r=await esbuild.build({bundle:true,platform:'browser',target:'es2022',minify:false,sourcemap:false,legalComments:'none',logLevel:'silent',metafile:true,banner:{js:banner},entryPoints:[resolve(entry)],outfile:resolve(out),format,write:false});
const contents=Buffer.from(r.outputFiles[0].contents),d=spawnSync('diff',['-u',out,'-'],{input:contents,encoding:'utf8',maxBuffer:4*1024*1024});
if(d.status!==0&&d.status!==1)throw new Error(d.stderr);
outputs.push({path:out,bytes:contents.length,sha256:createHash('sha256').update(contents).digest('hex'),patch:d.status===0?'':'*** Begin Patch\n*** Update File: '+resolve(out)+'\n'+d.stdout.split('\n').slice(2).join('\n').replace(/^@@.*@@.*$/gm,'@@')+'*** End Patch'});
}console.log(JSON.stringify(outputs));
NODE

attempts.command:
node --max-old-space-size=512 - <<'NODE'
const fs=require('fs'),{ESLint}=require('eslint'),path=require('path');
(async()=>{const b=JSON.parse(fs.readFileSync('docs/remediation/design/W35.02/baseline.json')),rows=await new ESLint().lintFiles(b.lint.rows.map(r=>r.path)),counts=a=>{const m=new Map();for(const v of a){const k=JSON.stringify(v);m.set(k,(m.get(k)||0)+1);}return m;};let errors=0,warnings=0;const additions=[],summary=[];for(const r of rows){const p=path.relative(process.cwd(),r.filePath),old=b.lint.rows.find(v=>v.path===p),prior=counts(old.signatures),current=counts(r.messages.filter(m=>m.severity===1).map(m=>[m.ruleId,m.message]));errors+=r.errorCount;warnings+=r.warningCount;for(const [key,n]of current)if(n>(prior.get(key)||0))additions.push({path:p,signature:JSON.parse(key),count:n,baseline:prior.get(key)||0});summary.push({path:p,errors:r.errorCount,warnings:r.warningCount,baseline:old.warnings});}console.log(JSON.stringify({errors,warnings,ceiling:131,new_signatures:additions,rows:summary}));if(errors||warnings>131||additions.length)process.exitCode=1;})().catch(e=>{console.error(e);process.exitCode=1;});
NODE
